import json

with open("workspace/network.json") as f:
    data = json.load(f)

T = data["time_periods"]
tg = data["thermal_generators"]
rg = data["renewable_generators"]

print("=== Thermal generator checks ===")
issues = []
must_run = []
on_at_t0 = []
for name, g in tg.items():
    pmin, pmax = g["power_output_minimum"], g["power_output_maximum"]
    if pmin > pmax: issues.append(f"{name}: pmin>pmax")
    if g["must_run"]: must_run.append(name)
    if g["unit_on_t0"]: on_at_t0.append((name, g["power_output_t0"], g["time_up_t0"]))
    # curve endpoints
    pts = [(p["mw"], p["cost"]) for p in g["piecewise_production"]]
    if abs(pts[0][0] - pmin) > 1e-9: issues.append(f"{name}: curve first mw {pts[0][0]} != pmin {pmin}")
    if abs(pts[-1][0] - pmax) > 1e-9: issues.append(f"{name}: curve last mw {pts[-1][0]} != pmax {pmax}")
    # convexity
    slopes = []
    for (x0,y0),(x1,y1) in zip(pts, pts[1:]):
        if x1 <= x0: issues.append(f"{name}: non-increasing mw in curve")
        slopes.append((y1-y0)/(x1-x0))
    for s0, s1 in zip(slopes, slopes[1:]):
        if s1 < s0 - 1e-9: issues.append(f"{name}: non-convex curve slopes {[round(s,4) for s in slopes]}")
    # startup tiers
    tiers = sorted(g["startup"], key=lambda x: x["lag"])
    lags = [t["lag"] for t in tiers]
    costs = [t["cost"] for t in tiers]
    if lags != sorted(lags): issues.append(f"{name}: tiers unsorted")
    for c0, c1 in zip(costs, costs[1:]):
        if c1 < c0: issues.append(f"{name}: startup cost decreasing {costs}")
    # ramp vs pmin
    if pmin > g["ramp_up_limit"] + 1e-9: issues.append(f"{name}: pmin {pmin} > ramp_up {g['ramp_up_limit']}")
    if pmin > g["ramp_startup_limit"] + 1e-9: issues.append(f"{name}: pmin {pmin} > ramp_startup {g['ramp_startup_limit']}")
    # initial state consistency
    if g["unit_on_t0"] == 1 and not (pmin - 1e-9 <= g["power_output_t0"] <= pmax + 1e-9):
        issues.append(f"{name}: on at t0 but p0={g['power_output_t0']} outside [pmin,pmax]")
    if g["unit_on_t0"] == 0 and g["power_output_t0"] != 0.0:
        issues.append(f"{name}: off at t0 but p0={g['power_output_t0']}")
    if g["unit_on_t0"] == 1 and g["time_up_t0"] == 0:
        issues.append(f"{name}: on at t0 but time_up_t0=0")
    if g["unit_on_t0"] == 0 and g["time_down_t0"] == 0:
        issues.append(f"{name}: off at t0 but time_down_t0=0")

print("issues:", issues if issues else "NONE")
print("must_run units:", must_run)
print("units on at t0:", on_at_t0)

# initial time_up / time_down distribution
import collections
print("\ntime_up_t0 values (on units):", collections.Counter(g["time_up_t0"] for g in tg.values() if g["unit_on_t0"]))
print("time_down_t0 < 12 (off units):", [(n, g["time_down_t0"]) for n, g in tg.items() if not g["unit_on_t0"] and g["time_down_t0"] < 12])
print("min_down values:", collections.Counter(g["time_down_minimum"] for g in tg.values()))
print("min_up values:", collections.Counter(g["time_up_minimum"] for g in tg.values()))
print("num startup tiers:", collections.Counter(len(g["startup"]) for g in tg.values()))
print("max startup lag:", max(max(t["lag"] for t in g["startup"]) for g in tg.values()))
print("num curve points:", collections.Counter(len(g["piecewise_production"]) for g in tg.values()))

print("\n=== Renewable checks ===")
rissues = []
fixed = 0
for name, r in rg.items():
    mn, mx = r["power_output_minimum"], r["power_output_maximum"]
    if len(mn) != T or len(mx) != T: rissues.append(f"{name}: length mismatch")
    for t in range(T):
        if mn[t] > mx[t] + 1e-9: rissues.append(f"{name} t{t}: min>max")
        if mn[t] < -1e-9 or mx[t] < -1e-9: rissues.append(f"{name} t{t}: negative")
    if all(abs(mn[t]-mx[t]) < 1e-9 for t in range(T)): fixed += 1
print("renewable issues:", rissues if rissues else "NONE")
print("renewables with min==max all periods:", fixed, "of", len(rg))

# system totals
renew_max_total = [sum(rg[r]["power_output_maximum"][t] for r in rg) for t in range(T)]
renew_min_total = [sum(rg[r]["power_output_minimum"][t] for r in rg) for t in range(T)]
demand = data["demand"]
resv = data["reserves"]
print("\n=== System balance feasibility ===")
for t in range(T):
    net = demand[t] - renew_min_total[t]  # thermal must produce at least this
    print(f"t={t+1:2d}: demand={demand[t]:8.2f} renew_min={renew_min_total[t]:7.2f} renew_max={renew_max_total[t]:7.2f} thermal_needed_min={demand[t]-renew_max_total[t]:8.2f} thermal_needed_max={demand[t]-renew_min_total[t]:8.2f} reserve={resv[t]:7.2f}")
"}

